from collections import defaultdict
def transform(g):
    h,w=len(g),len(g[0]); out=[r[:] for r in g]
    cnt=defaultdict(int)
    for r in g:
        for v in r: cnt[v]+=1
    bg=max(cnt,key=cnt.get)
    cells=defaultdict(list)
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg: cells[g[r][c]].append((r,c))
    for col,ps in cells.items():
        if len(ps)<2: continue
        for a in ps:
            for b in ps:
                if a>=b: continue
                dr,dc=b[0]-a[0],b[1]-a[1]
                if abs(dr)!=abs(dc): continue
                s=dr//abs(dr); t=dc//abs(dc)
                # count non-bg cells along the full diagonal
                line=[]
                r0,c0=a
                while 0<=r0<h and 0<=c0<w: r0-=s; c0-=t
                r0+=s; c0+=t
                while 0<=r0<h and 0<=c0<w:
                    if g[r0][c0]!=bg: line.append((r0,c0))
                    r0+=s; c0+=t
                if len(line)<3: continue
                for (r,c) in (a,b):
                    for d in (1,-1):
                        r0,c0=r+d*s,c+d*t
                        while 0<=r0<h and 0<=c0<w and out[r0][c0]==bg:
                            out[r0][c0]=col; r0+=d*s; c0+=d*t
    return out
